    agent_text_api_agent_post: {
        parameters: {
            query?: never;
            header?: never;
            path?: never;
            cookie?: never;
        };
        requestBody: {
            content: {
                "application/json": components["schemas"]["LogCreate"];
                "multipart/form-data": {
                    /** Format: binary */
                    audio?: string;
                    /** Format: uuid */
                    id: string;
                    /** Format: date-time */
                    captured_at: string;
                    tz: string;
                    /** @default false */
                    capture_fallback?: boolean;
                    capture_error?: string;
                    /** @description JSON array of AgentTurn — the chat so far (§6.4) */
                    history?: string;
                    /**
                     * Format: binary
                     * @description a plate photo — the §3.4b lane as a chat turn; exactly one of audio or image
                     */
                    image?: string;
                    /** @description said alongside an image — makes it a chat turn the agent can see (§6.4) */
                    text?: string;
                    /**
                     * Format: uuid
                     * @description the staged photo log this conversation is tuning (§3.4b)
                     */
                    photo_log_id?: string;
                    /** @description the phone's latitude when the photo was taken */
                    lat?: number;
                    /** @description the phone's longitude when the photo was taken */
                    lng?: number;
                    /** @description how far off that fix may be, in meters */
                    accuracy?: number;
                };
            };
        };
        responses: {
            /** @description A stream of newline-delimited JSON events, one AgentEvent per line, ending with `done` or `error`. */
            200: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/x-ndjson": components["schemas"]["AgentEvent"];
                };
            };
            /** @description Validation Error */
            422: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": components["schemas"]["HTTPValidationError"];
                };
            };
        };
    };
